      SUBROUTINE OGETCC     GETS FLOOR COORDINATE TRANSFER MATRIX FOR USE IN MISALIGNMENTC     CALCULATIONCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM0C.CIN'      INCLUDE 'ELM2B.CIN'      INCLUDE 'ELM2D.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM4E.CIN'      INCLUDE 'ELM8A.CIN'      INCLUDE 'ELM8D.CIN'      INCLUDE 'ELM8G.CIN'      INCLUDE 'ELM8H.CIN'      INCLUDE 'ELM8M.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM23.CIN'      INCLUDE 'OC.CIN'      INCLUDE 'OCS.CIN'      INCLUDE 'R2P.CIN'      INCLUDE 'R2PS.CIN'CC     LOCAL VARIABLESC      INTEGER         IDATA, IMAT, IMIS, ITYT, J, K, NSAVE, TYPECS      LOGICAL         BEFORS      EXTERNAL        IDATAC----------------------------------------------------------------CC     COORDINATE TRANSFORMATION STORED IN "ALIGN" ELEMENTC      IF (RORC .GE. 3) GO TO 50      IMIS = ISTOR(NMIS)      ITYT = IMIS + 9      DO 10 J = 1, 3   10 XR(J) = DATA(ITYT + J)      IMAT = ITYT + 3      DO 20 J = 1, 3      DO 20 K = 1, 3      IMAT = IMAT + 1      OR(J,K) = DATA(IMAT)   20 CONTINUE      GO TO 300CC     COORDINATE TRANSFORMATION CALCULATED FROM PRECEDING ELEMENTC   50 IF (LFM .GE. 1 .AND. BEFORE) GO TO 100      IF (TYPE .EQ. 2 .OR. (TYPE .EQ. 4 .AND. FFIN)) GO TO 70      IF (TYPE .EQ. 28 .OR. TYPE .EQ. 29) GO TO 70      DO 55 J = 1, 3      XR(J) = X0SV(J)   55 CONTINUE      DO 60 J = 1, 3      DO 60 K = 1, 3      OR(J,K) = OSV(J,K)   60 CONTINUE      GO TO 300C   70 DO 75 J = 1, 3      XR(J) = X0(3,J)   75 CONTINUE      DO 80 J = 1, 3      DO 80 K = 1, 3      OR(J,K) = O(3,J,K)   80 CONTINUE      GO TO 300CC     COORDINATE TRANSFORMATION CALCULATED FOR NEXT ELEMENTC  100 IF (TYPE .EQ. 2 .OR. TYPE .EQ. 4) GO TO 150      IF (TYPE .EQ. 28 .OR. TYPE .EQ. 29) GO TO 200      DO 105 J = 1, 3      XR(J) = 0.0  105 CONTINUE      DO 110 J = 1, 3      DO 110 K = 1, 3      OR(J,K) = 0.0  110 CONTINUE      DO 120 J = 1, 3      OR(J,J) = 1.0  120 CONTINUE      L = DATA(I+1)*UNITI(8)      XR(3) = L      GO TO 300CC     COORDINATE TRANSFORMATION FOR BENDING MAGNET TO COMEC  150 R2PS = R2P      DO 152 J = 1, 3      X0S(3,J) = X0(3,J)  152 CONTINUE      DO 155 J = 1, 3      DO 155 K = 1, 3      OS(3,J,K) = O(3,J,K)  155 CONTINUEC      NSAVE = NUM      TYPECS = TYPEC      BEFORS = BEFORE      R2P = .FALSE.      IF (TYPE .EQ. 4) GO TO 160      CALL OSET      CALL ADVANC(3)      R2P = .TRUE.C  157 NUM = NUM + NDIF      I = ISTOR(NUM)      TYPE = IDATA(I)      TYPEC = TYPE      IF (TYPE .EQ. 23) THEN        K1REG = IDATA(I+1)        K1TIE = TIE(I+1)        K2REG = IDATA(I+2)        K2TIE = TIE(I+2)        IOPN = IDATA(I+3)        JREG = IDATA(I+4)        JTIE = TIE(I+4)        CALL COMBIN      ENDIF      IF (NUM .NE. NUM4) GO TO 157C  160 L = LBEND      CALL OSET      CALL ADVANC(3)      R2P = .TRUE.C      IF (.NOT. FFIN .AND. DMC) GO TO 180      IF (FFIN .AND. DMC) GO TO 170      NUM = NUM2      I = ISTOR(NUM)      TYPE = IDATA(I)      CALL OSET      CALL ADVANC(3)C  170 DO 172 J = 1, 3      XR(J) = X0(3,J)  172 CONTINUE      DO 175 J = 1, 3      DO 175 K = 1, 3      OR(J,K) = O(3,J,K)  175 CONTINUE      GO TO 190C  180 DO 182 J = 1, 3      XR(J) = X0(1,J)  182 CONTINUE      DO 185 J = 1, 3      DO 185 K = 1, 3      OR(J,K) = O(1,J,K)  185 CONTINUE      GO TO 190C  190 NUM = NSAVE      I = ISTOR(NUM)      TYPE = IDATA(I)      TYPEC = TYPECS      BEFORE = BEFORSC      R2P = R2PS      DO 192 J = 1, 3      X0(3,J) = X0S(3,J)  192 CONTINUE      DO 195 J = 1, 3      DO 195 K = 1, 3      O(3,J,K) = OS(3,J,K)  195 CONTINUE      GO TO 300CC     COORDINATE TRANSFORMATION FOR RBEND OR SBEND TO COMEC  200 R2PS = R2P      TYPECS = TYPEC      DO 202 J = 1, 3      X0S(3,J) = X0(3,J)  202 CONTINUE      DO 205 J = 1, 3      DO 205 K = 1, 3      OS(3,J,K) = O(3,J,K)  205 CONTINUEC      BEFORS = BEFORE      R2P = .FALSE.      TYPEC = 2      CALL OSET      CALL ADVANC(3)      R2P = .TRUE.C      TYPEC = 4      L = LBEND      CALL OSET      CALL ADVANC(3)C      TYPEC = 2      CALL OSET      CALL ADVANC(3)C  220 DO 222 J = 1, 3      XR(J) = X0(3,J)  222 CONTINUE      DO 225 J = 1, 3      DO 225 K = 1, 3      OR(J,K) = O(3,J,K)  225 CONTINUEC      TYPEC = TYPECS      BEFORE = BEFORSC      R2P = R2PS      DO 242 J = 1, 3      X0(3,J) = X0S(3,J)  242 CONTINUE      DO 245 J = 1, 3      DO 245 K = 1, 3      O(3,J,K) = OS(3,J,K)  245 CONTINUE      GO TO 300C  300 IF (LTAB .EQ. 1)      1    STRATE(NM) = XR(1) .EQ. 0.0 .AND. XR(2) .EQ. 0.0      RETURN      END